/// A simplified AST node
#[derive(Debug, Clone)]
pub struct Node {
    pub kind: String,
    pub text: String,
    pub start_byte: usize,
    pub end_byte: usize,
    pub start_row: usize,
    pub start_col: usize,
    pub end_row: usize,
    pub end_col: usize,
    pub children: Vec<Node>,
    pub named: bool,
    pub field: Option<String>,
}

impl Node {
    pub fn new_leaf(kind: &str, text: &str, start_byte: usize, start_row: usize, start_col: usize, end_row: usize, end_col: usize) -> Self {
        Node {
            kind: kind.to_string(),
            text: text.to_string(),
            start_byte,
            end_byte: start_byte + text.len(),
            start_row,
            start_col,
            end_row,
            end_col,
            children: vec![],
            named: true,
            field: None,
        }
    }

    pub fn len_bytes(&self) -> usize {
        self.end_byte - self.start_byte
    }

    pub fn is_leaf(&self) -> bool {
        self.children.is_empty()
    }

    /// Get all named child nodes
    pub fn named_children(&self) -> Vec<&Node> {
        self.children.iter().filter(|c| c.named).collect()
    }

    /// Flatten: return all leaf nodes
    pub fn leaves(&self) -> Vec<&Node> {
        if self.children.is_empty() {
            vec![self]
        } else {
            self.children.iter().flat_map(|c| c.leaves()).collect()
        }
    }

    /// Walk all nodes
    pub fn walk(&self) -> Vec<&Node> {
        let mut result = vec![self];
        for child in &self.children {
            result.extend(child.walk());
        }
        result
    }
}

/// Position in source code
#[derive(Debug, Clone, Copy)]
pub struct Position {
    pub byte: usize,
    pub row: usize,
    pub col: usize,
}

/// Byte offset range
#[derive(Debug, Clone, Copy)]
pub struct ByteRange {
    pub start: usize,
    pub end: usize,
}
