    OpenParen,
    CloseParen,
    OpenBrace,
    CloseBrace,
    OpenBracket,
    CloseBracket,
    // Literals
    StringLit,
    NumberLit,
    // Identifiers and keywords
    Ident,
    // Operators and punctuation
    Op(String),
    // Whitespace and comments (usually skipped)
    Whitespace,
    LineComment,
    BlockComment,
    // Newline (significant in some languages)
    Newline,
    // End of file
    Eof,
}

#[derive(Debug, Clone)]
