//! Source code tokenizer and simplified AST builder
use crate::lang::Language;
use crate::node::Node;

/// Token type
#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    // Structural
    OpenParen,
    CloseParen,
    OpenBrace,
    CloseBrace,
    OpenBracket,
    CloseBracket,
    // Literals
    StringLit,
    NumberLit,
    // Identifiers and keywords
    Ident,
    // Operators and punctuation
    Op(String),
    // Whitespace and comments (usually skipped)
    Whitespace,
    LineComment,
    BlockComment,
    // Newline (significant in some languages)
    Newline,
    // End of file
    Eof,
}

#[derive(Debug, Clone)]
pub struct Token {
    pub kind: TokenKind,
    pub text: String,
    pub start_byte: usize,
    pub start_row: usize,
    pub start_col: usize,
    pub end_byte: usize,
    pub end_row: usize,
    pub end_col: usize,
}

/// Tokenize source code
pub struct Tokenizer<'a> {
    source: &'a [u8],
    pos: usize,
    row: usize,
    col: usize,
    lang: &'a Language,
}

impl<'a> Tokenizer<'a> {
    pub fn new(source: &'a [u8], lang: &'a Language) -> Self {
        Tokenizer { source, pos: 0, row: 0, col: 0, lang }
    }

    fn cur(&self) -> Option<u8> {
        self.source.get(self.pos).copied()
    }

    fn peek(&self, offset: usize) -> Option<u8> {
        self.source.get(self.pos + offset).copied()
    }

    fn advance(&mut self) -> Option<u8> {
        let ch = self.source.get(self.pos).copied()?;
        self.pos += 1;
        if ch == b'\n' {
            self.row += 1;
            self.col = 0;
        } else {
            self.col += 1;
        }
        Some(ch)
    }

    fn advance_n(&mut self, n: usize) {
        for _ in 0..n {
            self.advance();
        }
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.source.get(self.pos..).map_or(false, |rest| rest.starts_with(s))
    }

    fn read_string(&mut self, quote: u8) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        self.advance(); // opening quote
        let mut escaped = false;
        loop {
            match self.cur() {
                None => break,
                Some(b'\\') => {
                    escaped = !escaped;
                    self.advance();
                }
                Some(ch) if ch == quote && !escaped => {
                    self.advance();
                    break;
                }
                _ => {
                    escaped = false;
                    self.advance();
                }
            }
        }
        Token {
            kind: TokenKind::StringLit,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_triple_string(&mut self, quote: u8) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        self.advance_n(3); // opening triple quote
        loop {
            if self.pos + 3 > self.source.len() {
                self.pos = self.source.len();
                break;
            }
            if self.source[self.pos] == quote && self.source[self.pos+1] == quote && self.source[self.pos+2] == quote {
                self.advance_n(3);
                break;
            }
            self.advance();
        }
        Token {
            kind: TokenKind::StringLit,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_backtick_string(&mut self) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        self.advance(); // opening backtick
        let mut depth = 1i32;
        let mut escaped = false;
        loop {
            match self.cur() {
                None => break,
                Some(b'\\') => {
                    escaped = !escaped;
                    self.advance();
                }
                Some(b'`') if !escaped => {
                    self.advance();
                    break;
                }
                Some(b'$') if !escaped && self.peek(1) == Some(b'{') => {
                    // Template literal expression - just continue
                    escaped = false;
                    self.advance();
                }
                _ => {
                    escaped = false;
                    self.advance();
                }
            }
        }
        Token {
            kind: TokenKind::StringLit,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_line_comment(&mut self) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        while self.cur().map_or(false, |c| c != b'\n') {
            self.advance();
        }
        Token {
            kind: TokenKind::LineComment,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_block_comment(&mut self, end: &[u8]) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        while self.pos < self.source.len() {
            if self.source.get(self.pos..).map_or(false, |s| s.starts_with(end)) {
                self.advance_n(end.len());
                break;
            }
            self.advance();
        }
        Token {
            kind: TokenKind::BlockComment,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_number(&mut self) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        // Handle hex, octal, binary
        if self.cur() == Some(b'0') {
            self.advance();
            match self.cur() {
                Some(b'x') | Some(b'X') => {
                    self.advance();
                    while self.cur().map_or(false, |c| c.is_ascii_hexdigit() || c == b'_') {
                        self.advance();
                    }
                }
                Some(b'b') | Some(b'B') => {
                    self.advance();
                    while self.cur().map_or(false, |c| c == b'0' || c == b'1' || c == b'_') {
                        self.advance();
                    }
                }
                Some(b'o') | Some(b'O') => {
                    self.advance();
                    while self.cur().map_or(false, |c| c.is_ascii_digit() || c == b'_') {
                        self.advance();
                    }
                }
                _ => {
                    // Continue reading decimal
                    while self.cur().map_or(false, |c| c.is_ascii_digit() || c == b'.' || c == b'_' || c == b'e' || c == b'E') {
                        let c = self.cur().unwrap();
                        if c == b'.' && self.peek(1) == Some(b'.') {
                            break; // range operator
                        }
                        self.advance();
                    }
                }
            }
        } else {
            while self.cur().map_or(false, |c| c.is_ascii_digit() || c == b'.' || c == b'_' || c == b'e' || c == b'E') {
                let c = self.cur().unwrap();
                if c == b'.' && self.peek(1) == Some(b'.') {
                    break;
                }
                self.advance();
            }
        }
        // Suffix (like 'f32', 'i64', 'u8', etc. in Rust)
        while self.cur().map_or(false, |c| c.is_ascii_alphanumeric() || c == b'_') {
            let c = self.cur().unwrap();
            // Avoid consuming operators that start with letters after numbers
            if c.is_ascii_alphabetic() {
                // Check if it's a numeric suffix
                let text_so_far = &self.source[start_byte..self.pos];
                if text_so_far.iter().all(|&b| b.is_ascii_digit() || b == b'.' || b == b'_' || b == b'e' || b == b'E' || b == b'x' || b == b'X' || b == b'o' || b == b'O' || b == b'b' || b == b'B' || b.is_ascii_hexdigit()) {
                    // Could be a suffix
                    self.advance();
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        Token {
            kind: TokenKind::NumberLit,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    fn read_ident(&mut self) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;
        while self.cur().map_or(false, |c| c.is_ascii_alphanumeric() || c == b'_') {
            self.advance();
        }
        Token {
            kind: TokenKind::Ident,
            text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
            start_byte,
            start_row,
            start_col,
            end_byte: self.pos,
            end_row: self.row,
            end_col: self.col,
        }
    }

    pub fn next_token(&mut self) -> Token {
        let start_byte = self.pos;
        let start_row = self.row;
        let start_col = self.col;

        let ch = match self.cur() {
            None => return Token {
                kind: TokenKind::Eof,
                text: String::new(),
                start_byte, start_row, start_col,
                end_byte: self.pos, end_row: self.row, end_col: self.col,
            },
            Some(c) => c,
        };

        // Whitespace
        if ch == b'\n' {
            self.advance();
            return Token {
                kind: TokenKind::Newline,
                text: "\n".to_string(),
                start_byte, start_row, start_col,
                end_byte: self.pos, end_row: self.row, end_col: self.col,
            };
        }

        if ch.is_ascii_whitespace() {
            while self.cur().map_or(false, |c| c.is_ascii_whitespace() && c != b'\n') {
                self.advance();
            }
            return Token {
                kind: TokenKind::Whitespace,
                text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
                start_byte, start_row, start_col,
                end_byte: self.pos, end_row: self.row, end_col: self.col,
            };
        }

        // Numbers
        if ch.is_ascii_digit() {
            return self.read_number();
        }

        // Identifiers
        if ch.is_ascii_alphabetic() || ch == b'_' {
            // Check for language-specific string prefixes
            let is_string_prefix = match self.lang {
                Language::Python => matches!(ch, b'r' | b'b' | b'f' | b'R' | b'B' | b'F') && 
                    matches!(self.peek(1), Some(b'"') | Some(b'\'')),
                Language::Rust => matches!(ch, b'b') && matches!(self.peek(1), Some(b'"') | Some(b'\'')),
                _ => false,
            };
            if is_string_prefix {
                // Check if it's actually a string prefix
                let prefix_len = if matches!(self.peek(1), Some(b'"') | Some(b'\'')) { 1 } else { 0 };
                if prefix_len > 0 {
                    self.advance(); // consume prefix char
                    let q = self.cur().unwrap();
                    // Check for triple quote
                    if self.peek(1) == Some(q) && self.peek(2) == Some(q) {
                        // Don't handle triple quotes with prefix differently
                    }
                    return self.read_string(q);
                }
            }
            return self.read_ident();
        }

        // Unicode identifiers
        if ch >= 0x80 {
            // Multi-byte UTF-8 - treat as identifier part
            while self.cur().map_or(false, |c| c >= 0x80 || c.is_ascii_alphanumeric() || c == b'_') {
                self.advance();
            }
            return Token {
                kind: TokenKind::Ident,
                text: String::from_utf8_lossy(&self.source[start_byte..self.pos]).to_string(),
                start_byte, start_row, start_col,
                end_byte: self.pos, end_row: self.row, end_col: self.col,
            };
        }

        // Comments
        match self.lang {
            Language::Bash | Language::Python | Language::Ruby | Language::Yaml | Language::Elixir => {
                if ch == b'#' {
                    return self.read_line_comment();
                }
            }
            Language::Lua | Language::Haskell => {
                if ch == b'-' && self.peek(1) == Some(b'-') {
                    return self.read_line_comment();
                }
                if ch == b'-' && self.peek(1) == Some(b'-') && self.peek(2) == Some(b'[') {
                    // Block comment --[[ ... ]]
                    return self.read_block_comment(b"]]");
                }
            }
            Language::Html => {
                if self.starts_with(b"<!--") {
                    return self.read_block_comment(b"-->");
                }
            }
            Language::Css => {
                if self.starts_with(b"/*") {
                    return self.read_block_comment(b"*/");
                }
            }
            _ => {
                // C-style comments
                if self.starts_with(b"//") {
                    return self.read_line_comment();
                }
                if self.starts_with(b"/*") {
                    return self.read_block_comment(b"*/");
                }
            }
        }

        // Strings
        match ch {
            b'"' => {
                if self.peek(1) == Some(b'"') && self.peek(2) == Some(b'"') {
                    match self.lang {
                        Language::Python | Language::Kotlin | Language::Rust => {
                            return self.read_triple_string(b'"');
                        }
                        _ => {}
                    }
                }
                return self.read_string(b'"');
            }
            b'\'' => {
                if self.peek(1) == Some(b'\'') && self.peek(2) == Some(b'\'') {
                    match self.lang {
                        Language::Python => {
                            return self.read_triple_string(b'\'');
                        }
                        _ => {}
                    }
                }
                // In Rust, single char literals
                // In most languages, string
                return self.read_string(b'\'');
            }
            b'`' => {
                match self.lang {
                    Language::JavaScript | Language::TypeScript | Language::Tsx |
                    Language::Go | Language::Kotlin | Language::Scala => {
                        return self.read_backtick_string();
                    }
                    _ => {}
                }
            }
            _ => {}
        }

        // Structural tokens
        match ch {
            b'(' => { self.advance(); return Token { kind: TokenKind::OpenParen, text: "(".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            b')' => { self.advance(); return Token { kind: TokenKind::CloseParen, text: ")".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            b'{' => { self.advance(); return Token { kind: TokenKind::OpenBrace, text: "{".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            b'}' => { self.advance(); return Token { kind: TokenKind::CloseBrace, text: "}".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            b'[' => { self.advance(); return Token { kind: TokenKind::OpenBracket, text: "[".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            b']' => { self.advance(); return Token { kind: TokenKind::CloseBracket, text: "]".to_string(), start_byte, start_row, start_col, end_byte: self.pos, end_row: self.row, end_col: self.col }; }
            _ => {}
        }

        // Everything else is an operator/punctuation
        self.advance();
        Token {
            kind: TokenKind::Op(String::from_utf8_lossy(&[ch]).to_string()),
            text: String::from_utf8_lossy(&[ch]).to_string(),
            start_byte, start_row, start_col,
            end_byte: self.pos, end_row: self.row, end_col: self.col,
        }
    }

    /// Tokenize all tokens (including whitespace)
    pub fn tokenize_all(&mut self) -> Vec<Token> {
        let mut tokens = vec![];
        loop {
            let tok = self.next_token();
            let is_eof = matches!(tok.kind, TokenKind::Eof);
            tokens.push(tok);
            if is_eof {
                break;
            }
        }
        tokens
    }

    /// Tokenize, skipping whitespace and comments, but keeping newlines
    pub fn tokenize_significant(&mut self) -> Vec<Token> {
        self.tokenize_all().into_iter()
            .filter(|t| !matches!(t.kind, TokenKind::Whitespace | TokenKind::LineComment | TokenKind::BlockComment))
            .collect()
    }
}

/// Parse source code into a tree of nodes
pub fn parse(source: &str, lang: &Language) -> Node {
    let bytes = source.as_bytes();
    let mut tokenizer = Tokenizer::new(bytes, lang);
    let all_tokens = tokenizer.tokenize_significant();

    // Build a flat list of "items" which are tokens grouped by structural brackets
    let mut pos = 0;
    let root = parse_tokens(&all_tokens, &mut pos, None, source);
    root
}

/// Parse a sequence of tokens into a node tree
fn parse_tokens(tokens: &[Token], pos: &mut usize, end_kind: Option<&str>, source: &str) -> Node {
    let start_byte = tokens.get(*pos).map_or(source.len(), |t| t.start_byte);
    let start_row = tokens.get(*pos).map_or(0, |t| t.start_row);
    let start_col = tokens.get(*pos).map_or(0, |t| t.start_col);

    let mut children = Vec::new();

    while *pos < tokens.len() {
        let tok = &tokens[*pos];

        // Check if we should stop
        match &tok.kind {
            TokenKind::CloseParen if end_kind == Some(")") => break,
            TokenKind::CloseBrace if end_kind == Some("}") => break,
            TokenKind::CloseBracket if end_kind == Some("]") => break,
            TokenKind::Eof => break,
            _ => {}
        }

        match &tok.kind {
            TokenKind::OpenParen => {
                let group_start = *pos;
                let group_start_byte = tok.start_byte;
                let group_start_row = tok.start_row;
                let group_start_col = tok.start_col;
                *pos += 1; // consume '('
                let inner = parse_tokens(tokens, pos, Some(")"), source);
                let group_end_byte = tokens.get(*pos).map_or(group_start_byte + 1, |t| t.end_byte);
                let group_end_row = tokens.get(*pos).map_or(group_start_row, |t| t.end_row);
                let group_end_col = tokens.get(*pos).map_or(group_start_col + 1, |t| t.end_col);
                if *pos < tokens.len() { *pos += 1; } // consume ')'

                let mut group = Node {
                    kind: "paren_group".to_string(),
                    text: source.get(group_start_byte..group_end_byte).unwrap_or("").to_string(),
                    start_byte: group_start_byte,
                    end_byte: group_end_byte,
                    start_row: group_start_row,
                    start_col: group_start_col,
                    end_row: group_end_row,
                    end_col: group_end_col,
                    children: inner.children,
                    named: true,
                    field: None,
                };
                // Add open/close parens as children
                children.push(group);
            }
            TokenKind::OpenBrace => {
                let group_start_byte = tok.start_byte;
                let group_start_row = tok.start_row;
                let group_start_col = tok.start_col;
                *pos += 1;
                let inner = parse_tokens(tokens, pos, Some("}"), source);
                let group_end_byte = tokens.get(*pos).map_or(group_start_byte + 1, |t| t.end_byte);
                let group_end_row = tokens.get(*pos).map_or(group_start_row, |t| t.end_row);
                let group_end_col = tokens.get(*pos).map_or(group_start_col + 1, |t| t.end_col);
                if *pos < tokens.len() { *pos += 1; }

                let group = Node {
                    kind: "brace_group".to_string(),
                    text: source.get(group_start_byte..group_end_byte).unwrap_or("").to_string(),
                    start_byte: group_start_byte,
                    end_byte: group_end_byte,
                    start_row: group_start_row,
                    start_col: group_start_col,
                    end_row: group_end_row,
                    end_col: group_end_col,
                    children: inner.children,
                    named: true,
                    field: None,
                };
                children.push(group);
            }
            TokenKind::OpenBracket => {
                let group_start_byte = tok.start_byte;
                let group_start_row = tok.start_row;
                let group_start_col = tok.start_col;
                *pos += 1;
                let inner = parse_tokens(tokens, pos, Some("]"), source);
                let group_end_byte = tokens.get(*pos).map_or(group_start_byte + 1, |t| t.end_byte);
                let group_end_row = tokens.get(*pos).map_or(group_start_row, |t| t.end_row);
                let group_end_col = tokens.get(*pos).map_or(group_start_col + 1, |t| t.end_col);
                if *pos < tokens.len() { *pos += 1; }

                let group = Node {
                    kind: "bracket_group".to_string(),
                    text: source.get(group_start_byte..group_end_byte).unwrap_or("").to_string(),
                    start_byte: group_start_byte,
                    end_byte: group_end_byte,
                    start_row: group_start_row,
                    start_col: group_start_col,
                    end_row: group_end_row,
                    end_col: group_end_col,
                    children: inner.children,
                    named: true,
                    field: None,
                };
                children.push(group);
            }
            _ => {
                // Leaf node
                let leaf = token_to_node(tok);
                *pos += 1;
                children.push(leaf);
            }
        }
    }

    let end_byte = children.last().map_or(start_byte, |c| c.end_byte);
    let end_row = children.last().map_or(start_row, |c| c.end_row);
    let end_col = children.last().map_or(start_col, |c| c.end_col);

    Node {
        kind: "program".to_string(),
        text: source.get(start_byte..end_byte).unwrap_or("").to_string(),
        start_byte,
        end_byte,
        start_row,
        start_col,
        end_row,
        end_col,
        children,
        named: true,
        field: None,
    }
}

fn token_to_node(tok: &Token) -> Node {
    let kind = match &tok.kind {
        TokenKind::Ident => "identifier",
        TokenKind::StringLit => "string",
        TokenKind::NumberLit => "number",
        TokenKind::OpenParen => "(",
        TokenKind::CloseParen => ")",
        TokenKind::OpenBrace => "{",
        TokenKind::CloseBrace => "}",
        TokenKind::OpenBracket => "[",
        TokenKind::CloseBracket => "]",
        TokenKind::Newline => "newline",
        TokenKind::Eof => "eof",
        TokenKind::LineComment => "line_comment",
        TokenKind::BlockComment => "block_comment",
        TokenKind::Whitespace => "whitespace",
        TokenKind::Op(s) => "operator",
    };
    Node {
        kind: kind.to_string(),
        text: tok.text.clone(),
        start_byte: tok.start_byte,
        end_byte: tok.end_byte,
        start_row: tok.start_row,
        start_col: tok.start_col,
        end_row: tok.end_row,
        end_col: tok.end_col,
        children: vec![],
        named: !matches!(tok.kind, TokenKind::Op(_) | TokenKind::Newline | TokenKind::OpenParen | TokenKind::CloseParen | TokenKind::OpenBrace | TokenKind::CloseBrace | TokenKind::OpenBracket | TokenKind::CloseBracket),
        field: None,
    }
}
