//! Pattern parsing and matching
use crate::lang::Language;
use crate::parse::{Token, TokenKind, Tokenizer};
use std::collections::HashMap;

/// A pattern token - either a literal or a metavariable
#[derive(Debug, Clone)]
pub enum PatToken {
    /// A literal token that must match exactly (or close enough)
    Literal { text: String, kind: TokenKind },
    /// A single-node metavariable $NAME
    MetaVar(String),
    /// A multi-node metavariable $$$NAME
    MetaVarMulti(String),
}

impl PatToken {
    pub fn is_meta(&self) -> bool {
        matches!(self, PatToken::MetaVar(_) | PatToken::MetaVarMulti(_))
    }

    pub fn meta_name(&self) -> Option<&str> {
        match self {
            PatToken::MetaVar(n) => Some(n),
            PatToken::MetaVarMulti(n) => Some(n),
            _ => None,
        }
    }
}

/// Parse a pattern string into pattern tokens
pub fn parse_pattern(pattern: &str, lang: &Language) -> Vec<PatToken> {
    let bytes = pattern.as_bytes();
    let mut tokenizer = Tokenizer::new(bytes, lang);
    let tokens = tokenizer.tokenize_significant();

    tokens.into_iter().filter_map(|tok| {
        match &tok.kind {
            TokenKind::Newline | TokenKind::Eof => None,
            TokenKind::Ident => {
                // Check if it's a metavar: starts with $
                // Actually metavars use $ which is an Op
                Some(PatToken::Literal { text: tok.text, kind: tok.kind })
            }
            TokenKind::Op(s) if s == "$" => {
                // This is a metavar start - but since $ is just an Op,
                // we need to look at context
                // Since we've already tokenized, we need to handle this differently
                // Let's just pass it through
                Some(PatToken::Literal { text: tok.text, kind: tok.kind })
            }
            _ => Some(PatToken::Literal { text: tok.text, kind: tok.kind })
        }
    }).collect()
}

/// Parse a pattern string into a MetaPattern that handles metavariables
pub fn parse_meta_pattern(pattern: &str, lang: &Language) -> Vec<PatToken> {
    // We need to detect metavariables: $NAME or $$$NAME
    // First, let's find all metavar positions in the pattern

    let bytes = pattern.as_bytes();
    let mut result = Vec::new();
    let mut i = 0;

    while i < bytes.len() {
        if bytes[i] == b'$' {
            // Check for $$$ (multi-node metavar)
            let multi = i + 2 < bytes.len() && bytes[i+1] == b'$' && bytes[i+2] == b'$';
            let start = if multi { i + 3 } else { i + 1 };

            // Read the name (identifier chars)
            let mut j = start;
            while j < bytes.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
                j += 1;
            }

            if j > start {
                let name = std::str::from_utf8(&bytes[start..j]).unwrap().to_string();
                if multi {
                    result.push(PatToken::MetaVarMulti(name));
                } else {
                    result.push(PatToken::MetaVar(name));
                }
                i = j;
            } else {
                // Not a metavar, just a $ sign
                result.push(PatToken::Literal { 
                    text: "$".to_string(), 
                    kind: TokenKind::Op("$".to_string()) 
                });
                i += 1;
            }
        } else {
            // Parse a regular token
            let tok_start = i;
            let mut tokenizer = Tokenizer::new(&bytes[i..], lang);
            let tok = tokenizer.next_token();
            if matches!(tok.kind, TokenKind::Eof) {
                break;
            }
            i += tok.text.len().max(1);
            if !matches!(tok.kind, TokenKind::Whitespace | TokenKind::Newline | TokenKind::LineComment | TokenKind::BlockComment) {
                result.push(PatToken::Literal { text: tok.text, kind: tok.kind });
            }
        }
    }

    result
}

/// A metavariable binding
#[derive(Debug, Clone)]
pub struct MetaBinding {
    pub text: String,
    pub start_byte: usize,
    pub end_byte: usize,
    pub start_row: usize,
    pub start_col: usize,
    pub end_row: usize,
    pub end_col: usize,
}

/// Multi-node metavariable binding
#[derive(Debug, Clone)]
pub struct MultiBinding {
    pub items: Vec<MetaBinding>,
}

/// Result of a pattern match
#[derive(Debug, Clone)]
pub struct MatchResult {
    pub start_byte: usize,
    pub end_byte: usize,
    pub start_row: usize,
    pub start_col: usize,
    pub end_row: usize,
    pub end_col: usize,
    pub text: String,
    pub single_vars: HashMap<String, MetaBinding>,
    pub multi_vars: HashMap<String, MultiBinding>,
}
