//! Core pattern matching logic
use crate::lang::Language;
use crate::pattern::{PatToken, MetaBinding, MultiBinding, MatchResult, parse_meta_pattern};
use crate::parse::{Token, TokenKind, Tokenizer};
use std::collections::HashMap;

/// A source token with position info
#[derive(Debug, Clone)]
struct SrcToken {
    text: String,
    kind: TokenKind,
    start_byte: usize,
    end_byte: usize,
    start_row: usize,
    start_col: usize,
    end_row: usize,
    end_col: usize,
    depth: i32, // nesting depth
}

/// Tokenize source code into a flat list of tokens with depth info
fn tokenize_with_depth(source: &str, lang: &Language) -> Vec<SrcToken> {
    let bytes = source.as_bytes();
    let mut tokenizer = Tokenizer::new(bytes, lang);
    let raw_tokens = tokenizer.tokenize_significant();

    let mut depth = 0i32;
    let mut result = Vec::new();

    for tok in raw_tokens {
        if matches!(tok.kind, TokenKind::Eof) {
            break;
        }
        if matches!(tok.kind, TokenKind::Newline) {
            continue;
        }

        let d = match &tok.kind {
            TokenKind::OpenParen | TokenKind::OpenBrace | TokenKind::OpenBracket => {
                let old = depth;
                depth += 1;
                old
            }
            TokenKind::CloseParen | TokenKind::CloseBrace | TokenKind::CloseBracket => {
                depth -= 1;
                if depth < 0 { depth = 0; }
                depth
            }
            _ => depth,
        };

        result.push(SrcToken {
            text: tok.text,
            kind: tok.kind,
            start_byte: tok.start_byte,
            end_byte: tok.end_byte,
            start_row: tok.start_row,
            start_col: tok.start_col,
            end_row: tok.end_row,
            end_col: tok.end_col,
            depth: d,
        });
    }

    result
}

/// Check if a token can start a "node" (single metavar match)
/// Returns the extent of that node (end index exclusive)
fn node_extent(tokens: &[SrcToken], start: usize) -> usize {
    if start >= tokens.len() {
        return start;
    }

    let tok = &tokens[start];

    // For open brackets, the extent is the matching close bracket
    match &tok.kind {
        TokenKind::OpenParen | TokenKind::OpenBrace | TokenKind::OpenBracket => {
            let depth_start = tok.depth;
            let mut i = start + 1;
            while i < tokens.len() {
                let t = &tokens[i];
                if matches!(t.kind, TokenKind::CloseParen | TokenKind::CloseBrace | TokenKind::CloseBracket)
                    && t.depth <= depth_start {
                    return i + 1;
                }
                i += 1;
            }
            tokens.len()
        }
        _ => start + 1,
    }
}

/// Match pattern tokens against source tokens starting at position `src_pos`
/// Returns (end_pos, bindings) if match succeeds
fn try_match<'a>(
    pattern: &[PatToken],
    src: &'a [SrcToken],
    pat_pos: usize,
    src_pos: usize,
    bindings: &mut HashMap<String, MetaBinding>,
    multi_bindings: &mut HashMap<String, MultiBinding>,
) -> Option<usize> {
    if pat_pos == pattern.len() {
        return Some(src_pos);
    }

    if src_pos > src.len() {
        return None;
    }

    let pat = &pattern[pat_pos];

    match pat {
        PatToken::MetaVarMulti(name) => {
            // Try to match 0 or more tokens until the rest of pattern matches
            // First, check if this name is already bound
            if let Some(existing) = multi_bindings.get(name) {
                // Need to match exactly those tokens
                let expected: Vec<_> = existing.items.clone();
                let end = src_pos + expected.len();
                if end > src.len() {
                    return None;
                }
                for (i, item) in expected.iter().enumerate() {
                    if src[src_pos + i].text != item.text {
                        return None;
                    }
                }
                return try_match(pattern, src, pat_pos + 1, end, bindings, multi_bindings);
            }

            // Try matching different numbers of tokens
            // The next pattern element tells us when to stop
            let mut end = src_pos;

            // Gather all possible end positions within the current depth level
            let base_depth = src.get(src_pos).map_or(0, |t| t.depth);

            while end <= src.len() {
                // Try the rest of the pattern at 'end'
                let mut new_bindings = bindings.clone();
                let mut new_multi_bindings = multi_bindings.clone();

                // Collect the tokens from src_pos to end
                let items: Vec<MetaBinding> = src[src_pos..end].iter().map(|t| MetaBinding {
                    text: t.text.clone(),
                    start_byte: t.start_byte,
                    end_byte: t.end_byte,
                    start_row: t.start_row,
                    start_col: t.start_col,
                    end_row: t.end_row,
                    end_col: t.end_col,
                }).collect();

                new_multi_bindings.insert(name.clone(), MultiBinding { items });

                if let Some(result) = try_match(pattern, src, pat_pos + 1, end, &mut new_bindings, &mut new_multi_bindings) {
                    *bindings = new_bindings;
                    *multi_bindings = new_multi_bindings;
                    return Some(result);
                }

                if end >= src.len() {
                    break;
                }

                // Advance by one node
                let next = node_extent(src, end);
                if next == end {
                    end += 1;
                } else {
                    // Include the whole group
                    end = next;
                }
            }

            None
        }

        PatToken::MetaVar(name) => {
            if src_pos >= src.len() {
                return None;
            }

            // Check if this name is already bound
            if let Some(existing) = bindings.get(name) {
                let existing_text = existing.text.clone();
                // Try to match the same extent
                let extent = node_extent(src, src_pos);
                let matched_text: String = src[src_pos..extent].iter().map(|t| t.text.as_str()).collect::<Vec<_>>().join("");
                // Simple check: the text should match
                // But we need to reconstruct with whitespace...
                // For now, just check if the first token matches
                if src[src_pos].text == existing.text {
                    return try_match(pattern, src, pat_pos + 1, src_pos + 1, bindings, multi_bindings);
                }
                return None;
            }

            // Match a single "node" - which is either one token or a bracketed group
            let extent = node_extent(src, src_pos);
            if extent <= src_pos {
                return None;
            }

            // Collect all tokens in this node
            let node_tokens = &src[src_pos..extent];

            // Check this doesn't violate any constraints
            // For now, accept any node

            // Build the binding text
            let node_text = reconstruct_text(node_tokens);
            let node_start_byte = node_tokens.first().map_or(0, |t| t.start_byte);
            let node_end_byte = node_tokens.last().map_or(0, |t| t.end_byte);
            let node_start_row = node_tokens.first().map_or(0, |t| t.start_row);
            let node_start_col = node_tokens.first().map_or(0, |t| t.start_col);
            let node_end_row = node_tokens.last().map_or(0, |t| t.end_row);
            let node_end_col = node_tokens.last().map_or(0, |t| t.end_col);

            let old = bindings.insert(name.clone(), MetaBinding {
                text: node_text,
                start_byte: node_start_byte,
                end_byte: node_end_byte,
                start_row: node_start_row,
                start_col: node_start_col,
                end_row: node_end_row,
                end_col: node_end_col,
            });

            let result = try_match(pattern, src, pat_pos + 1, extent, bindings, multi_bindings);

            if result.is_none() {
                if let Some(old_val) = old {
                    bindings.insert(name.clone(), old_val);
                } else {
                    bindings.remove(name);
                }
            }

            result
        }

        PatToken::Literal { text, kind } => {
            if src_pos >= src.len() {
                return None;
            }

            let src_tok = &src[src_pos];

            // Check if tokens match
            if tokens_match(text, kind, &src_tok.text, &src_tok.kind) {
                try_match(pattern, src, pat_pos + 1, src_pos + 1, bindings, multi_bindings)
            } else {
                None
            }
        }
    }
}

fn tokens_match(pat_text: &str, pat_kind: &TokenKind, src_text: &str, src_kind: &TokenKind) -> bool {
    // Structural tokens must match exactly
    match (pat_kind, src_kind) {
        (TokenKind::OpenParen, TokenKind::OpenParen) |
        (TokenKind::CloseParen, TokenKind::CloseParen) |
        (TokenKind::OpenBrace, TokenKind::OpenBrace) |
        (TokenKind::CloseBrace, TokenKind::CloseBrace) |
        (TokenKind::OpenBracket, TokenKind::OpenBracket) |
        (TokenKind::CloseBracket, TokenKind::CloseBracket) => return true,
        (TokenKind::OpenParen, _) | (_, TokenKind::OpenParen) |
        (TokenKind::CloseParen, _) | (_, TokenKind::CloseParen) |
        (TokenKind::OpenBrace, _) | (_, TokenKind::OpenBrace) |
        (TokenKind::CloseBrace, _) | (_, TokenKind::CloseBrace) |
        (TokenKind::OpenBracket, _) | (_, TokenKind::OpenBracket) |
        (TokenKind::CloseBracket, _) | (_, TokenKind::CloseBracket) => return false,
        _ => {}
    }

    // For other tokens, check text equality
    pat_text == src_text
}

fn reconstruct_text(tokens: &[SrcToken]) -> String {
    if tokens.is_empty() {
        return String::new();
    }
    // Use original byte positions to extract text from source
    // For now, we'll reconstruct from token texts
    // In reality, this would use the original source bytes
    tokens.iter().map(|t| t.text.as_str()).collect::<Vec<_>>().join("")
}

/// Find all matches of pattern in source
pub fn find_matches(pattern_str: &str, source: &str, lang: &Language) -> Vec<MatchResult> {
    let pattern = parse_meta_pattern(pattern_str, lang);
    if pattern.is_empty() {
        return vec![];
    }

    let src_tokens = tokenize_with_depth(source, lang);
    let src_bytes = source.as_bytes();

    let mut results = Vec::new();
    let mut i = 0;

    while i < src_tokens.len() {
        let mut bindings = HashMap::new();
        let mut multi_bindings = HashMap::new();

        if let Some(end_pos) = try_match(&pattern, &src_tokens, 0, i, &mut bindings, &mut multi_bindings) {
            if end_pos > i {
                let start_byte = src_tokens[i].start_byte;
                let end_byte = src_tokens[end_pos - 1].end_byte;
                let start_row = src_tokens[i].start_row;
                let start_col = src_tokens[i].start_col;
                let end_row = src_tokens[end_pos - 1].end_row;
                let end_col = src_tokens[end_pos - 1].end_col;

                // Extract the actual text from source
                let text = source.get(start_byte..end_byte).unwrap_or("").to_string();

                results.push(MatchResult {
                    start_byte,
                    end_byte,
                    start_row,
                    start_col,
                    end_row,
                    end_col,
                    text,
                    single_vars: bindings,
                    multi_vars: multi_bindings,
                });

                // Advance by 1 to find overlapping matches
                i += 1;
            } else {
                i += 1;
            }
        } else {
            i += 1;
        }
    }

    // Deduplicate overlapping matches (keep longest/first)
    deduplicate_matches(results)
}

fn deduplicate_matches(mut matches: Vec<MatchResult>) -> Vec<MatchResult> {
    if matches.len() <= 1 {
        return matches;
    }

    // Sort by start position, then by length (longer first)
    matches.sort_by(|a, b| {
        a.start_byte.cmp(&b.start_byte)
            .then(b.end_byte.cmp(&a.end_byte))
    });

    let mut result = Vec::new();
    let mut last_end = 0;

    for m in matches {
        if m.start_byte >= last_end {
            last_end = m.end_byte;
            result.push(m);
        }
    }

    result
}
