/// Get the source lines that contain the match
pub fn get_match_lines(source: &str, start_byte: usize, end_byte: usize) -> String {
    // Find the start of the first line
    let line_start = source[..start_byte].rfind('\n').map_or(0, |p| p + 1);
    // Find the end of the last line
    let line_end = source[end_byte..].find('\n').map_or(source.len(), |p| end_byte + p);
    source[line_start..line_end].to_string()
}

/// Get char counts (leading chars before match on first line, trailing after match on last line)
pub fn get_char_counts(source: &str, start_byte: usize, end_byte: usize) -> (usize, usize) {
    // Leading: chars from start of first line to start of match
    let line_start = source[..start_byte].rfind('\n').map_or(0, |p| p + 1);
    let leading = source[line_start..start_byte].chars().count();

    // Trailing: chars from end of match to end of last line
    let line_end = source[end_byte..].find('\n').map_or(source.len(), |p| end_byte + p);
    let trailing = source[end_byte..line_end].chars().count();

    (leading, trailing)
}

pub fn json_str(s: &str) -> String {
    let mut out = String::new();
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 32 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
