//! Command-line interface for ast-grep
use std::fs;
use std::io::{self, Read, Write, BufRead};
use std::path::Path;
use crate::lang::Language;
use crate::matcher::find_matches;
use crate::pattern::MatchResult;
use crate::output::{match_to_json, get_match_lines, get_char_counts, json_str};

pub fn run(args: Vec<String>) -> i32 {
    // Parse args manually
    let prog = args.get(0).map(|s| s.as_str()).unwrap_or("ast-grep");
    let args_slice = &args[1..];

    if args_slice.is_empty() {
        print_help(prog);
        return 1;
    }

    match args_slice[0].as_str() {
        "--help" | "-h" => {
            print_main_help(prog);
            return 0;
        }
        "--version" | "-V" => {
            println!("ast-grep 0.42.1");
            return 0;
        }
        "run" => run_cmd(prog, &args_slice[1..]),
        "scan" => scan_cmd(prog, &args_slice[1..]),
        "test" => test_cmd(prog, &args_slice[1..]),
        "new" => new_cmd(prog, &args_slice[1..]),
        "lsp" => lsp_cmd(prog, &args_slice[1..]),
        "completions" => completions_cmd(prog, &args_slice[1..]),
        "help" => {
            if let Some(sub) = args_slice.get(1) {
                match sub.as_str() {
                    "run" => { print_run_help(prog); 0 }
                    "scan" => { print_scan_help(prog); 0 }
                    "test" => { print_test_help(prog); 0 }
                    "new" => { print_new_help(prog); 0 }
                    "lsp" => { print_lsp_help(prog); 0 }
                    "completions" => { print_completions_help(prog); 0 }
                    _ => { print_main_help(prog); 0 }
                }
            } else {
                print_main_help(prog);
                0
            }
        }
        // If first arg is --pattern, treat as 'run' command
        arg if arg.starts_with('-') || arg.starts_with('.') || arg.starts_with('/') => {
            // Default subcommand is 'run'
            run_cmd(prog, args_slice)
        }
        _ => {
            // Could be a path argument for default run
            run_cmd(prog, args_slice)
        }
    }
}

fn print_help(prog: &str) {
    print_main_help(prog);
}

fn print_main_help(prog: &str) {
    eprintln!("Search and Rewrite code at large scale using AST pattern.");
    eprintln!("                    __");
    eprintln!("        ____ ______/ /_      ____ _________  ____");
    eprintln!("       / __ `/ ___/ __/_____/ __ `/ ___/ _ \\/ __ \\");
    eprintln!("      / /_/ (__  ) /_/_____/ /_/ / /  /  __/ /_/ /");
    eprintln!("      \\__,_/____/\\__/      \\__, /_/   \\___/ .___/");
    eprintln!("                          /____/         /_/");
    eprintln!("");
    eprintln!("");
    eprintln!("Usage: {} [OPTIONS] <COMMAND>", prog);
    eprintln!("");
    eprintln!("Commands:");
    eprintln!("  run          Run one time search or rewrite in command line. (default command)");
    eprintln!("  scan         Scan and rewrite code by configuration");
