#[derive(Debug, Clone)]
pub struct Rule {
    pub id: String,
    pub language: String,
    pub pattern: String,
    pub message: String,
    pub severity: String,
    pub note: Option<String>,
}

fn load_rule_file(path: &str) -> Result<Vec<Rule>, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Cannot read file: {}", e))?;
    parse_rules_yaml(&content)
}

fn parse_rules_yaml(yaml: &str) -> Result<Vec<Rule>, String> {
    let mut rules = Vec::new();

    // Simple YAML parser for rule format
    for doc in yaml.split("---") {
        let doc = doc.trim();
        if doc.is_empty() {
            continue;
        }

        if let Some(rule) = parse_single_rule(doc) {
            rules.push(rule);
        }
    }

    if rules.is_empty() {
        return Err("No valid rules found in YAML".to_string());
    }

    Ok(rules)
}

fn parse_single_rule(yaml: &str) -> Option<Rule> {
    let id = extract_yaml_str(yaml, "id")?;
    let language = extract_yaml_str(yaml, "language")?;
    let pattern = extract_rule_pattern(yaml)?;
    let message = extract_yaml_str(yaml, "message").unwrap_or_else(|| id.clone());
    let severity = extract_yaml_str(yaml, "severity").unwrap_or_else(|| "warning".to_string());
    let note = extract_yaml_str(yaml, "note");

    Some(Rule { id, language, pattern, message, severity, note })
}

fn extract_yaml_str(yaml: &str, key: &str) -> Option<String> {
    for line in yaml.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with(&format!("{}:", key)) {
            let val = trimmed[key.len()+1..].trim();
            // Remove surrounding quotes if present
            let val = if (val.starts_with('"') && val.ends_with('"')) ||
                         (val.starts_with('\'') && val.ends_with('\'')) {
                val[1..val.len()-1].to_string()
            } else {
                val.to_string()
            };
            if !val.is_empty() {
                return Some(val);
            }
        }
    }
    None
}

fn extract_rule_pattern(yaml: &str) -> Option<String> {
    // Look for: rule:\n  pattern: <PATTERN>
    // Or: rule:\n  pattern: |\n    <multiline>
    let mut in_rule = false;
    let mut in_pattern = false;
    let mut multiline = false;
    let mut pattern_lines = Vec::new();
    let mut pattern_indent = 0;

    for line in yaml.lines() {
        let trimmed = line.trim();

        if trimmed == "rule:" || trimmed.starts_with("rule:") {
            in_rule = true;
            in_pattern = false;
            continue;
        }

        if in_rule {
            let indent = line.len() - line.trim_start().len();

            if trimmed.starts_with("pattern:") {
                let val = trimmed["pattern:".len()..].trim();
                if val == "|" || val == "|-" {
                    in_pattern = true;
                    multiline = true;
                    pattern_indent = 0;
                } else if !val.is_empty() {
                    let val = if (val.starts_with('"') && val.ends_with('"')) ||
                                 (val.starts_with('\'') && val.ends_with('\'')) {
                        val[1..val.len()-1].to_string()
                    } else {
                        val.to_string()
                    };
                    return Some(val);
                }
                continue;
            }

            if in_pattern && multiline {
                if line.trim().is_empty() {
                    pattern_lines.push(String::new());
                    continue;
                }
                let cur_indent = line.len() - line.trim_start().len();
                if pattern_indent == 0 && !line.trim().is_empty() {
                    pattern_indent = cur_indent;
                }
                if cur_indent < pattern_indent && !line.trim().is_empty() {
                    // End of multiline pattern
                    break;
                }
                let stripped = if cur_indent >= pattern_indent {
                    &line[pattern_indent..]
                } else {
                    line.trim()
                };
                pattern_lines.push(stripped.to_string());
                continue;
            }

            // If we see something at lower indent, we're out of rule section
            if indent <= 0 && !trimmed.is_empty() && !trimmed.starts_with(' ') && !trimmed.starts_with('\t') {
                in_rule = false;
            }
        }
    }

    if !pattern_lines.is_empty() {
        Some(pattern_lines.join("\n").trim().to_string())
    } else {
        None
    }
}

fn load_config_rules(config_file: &str) -> Result<Vec<Rule>, String> {
    let config = fs::read_to_string(config_file)
        .map_err(|e| format!("Cannot read config file '{}': {}. Provide a rule file with --rule.", config_file, e))?;

    // Parse sgconfig.yml to get rule dirs
    let rule_dirs = extract_yaml_list(&config, "ruleDirs");

    let mut all_rules = Vec::new();
    for dir in rule_dirs {
        if let Ok(entries) = fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|e| e.to_str()) == Some("yml") ||
                   path.extension().and_then(|e| e.to_str()) == Some("yaml") {
                    if let Ok(rules) = load_rule_file(&path.to_string_lossy()) {
                        all_rules.extend(rules);
                    }
                }
            }
        }
    }

    Ok(all_rules)
}

fn extract_yaml_list(yaml: &str, key: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut in_list = false;

    for line in yaml.lines() {
        let trimmed = line.trim();
        if trimmed == &format!("{}:", key) {
            in_list = true;
            continue;
        }
        if in_list {
            if trimmed.starts_with("- ") {
                result.push(trimmed[2..].trim().to_string());
            } else if !trimmed.is_empty() && !trimmed.starts_with(' ') && !trimmed.starts_with('\t') {
                break;
            }
        }
    }

    result
}

