fn compact_json(json: &str) -> String {
    let mut result = String::new();
    let mut in_string = false;
    let mut escaped = false;

    for ch in json.chars() {
        if escaped {
            result.push(ch);
            escaped = false;
            continue;
        }

        if ch == '\\' && in_string {
            result.push(ch);
            escaped = true;
            continue;
        }

        if ch == '"' {
            in_string = !in_string;
            result.push(ch);
            continue;
        }

        if in_string {
            result.push(ch);
            continue;
        }

        // Skip whitespace outside strings
        if ch.is_whitespace() {
            continue;
        }

        result.push(ch);
    }

    result
}
