fn extract_yaml_test_configs(yaml: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut in_section = false;

    for line in yaml.lines() {
        let trimmed = line.trim();
        if trimmed == "testConfigs:" {
            in_section = true;
            continue;
        }
        if in_section {
            if trimmed.starts_with("- testDir:") {
                let dir = trimmed["- testDir:".len()..].trim().to_string();
                result.push(dir);
            } else if trimmed.starts_with("  testDir:") {
                let dir = trimmed["  testDir:".len()..].trim().to_string();
                result.push(dir);
            } else if !trimmed.is_empty() && !trimmed.starts_with('-') && !trimmed.starts_with(' ') {
                break;
            }
        }
    }

    result
}

