/// Parse command-line arguments into a hashmap
struct Args {
    positional: Vec<String>,
    flags: std::collections::HashMap<String, Option<String>>,
    bool_flags: std::collections::HashSet<String>,
    multi_flags: std::collections::HashMap<String, Vec<String>>,
}

impl Args {
    fn new() -> Self {
        Args {
            positional: vec![],
            flags: std::collections::HashMap::new(),
            bool_flags: std::collections::HashSet::new(),
            multi_flags: std::collections::HashMap::new(),
        }
    }

    fn get(&self, name: &str) -> Option<&str> {
        self.flags.get(name).and_then(|v| v.as_deref())
    }

    fn has(&self, name: &str) -> bool {
        self.bool_flags.contains(name) || self.flags.contains_key(name)
    }

    fn get_multi(&self, name: &str) -> &[String] {
        self.multi_flags.get(name).map(|v| v.as_slice()).unwrap_or(&[])
    }
}

fn parse_args(args: &[String]) -> Result<Args, String> {
    let mut result = Args::new();
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--" {
            i += 1;
            while i < args.len() {
                result.positional.push(args[i].clone());
                i += 1;
            }
            break;
        }

        if arg.starts_with("--") {
            let key = &arg[2..];
            // Handle --key=value
            if let Some(eq) = key.find('=') {
                let k = key[..eq].to_string();
                let v = key[eq+1..].to_string();
                // Multi-value flags
                if matches!(k.as_str(), "no-ignore" | "globs" | "error" | "warning" | "info" | "hint" | "off") {
                    result.multi_flags.entry(k).or_default().push(v);
                } else {
                    result.flags.insert(k, Some(v));
                }
            } else {
                // Check if next arg is a value
                let k = key.to_string();
                // Boolean flags
                if matches!(k.as_str(), "stdin" | "interactive" | "update-all" | "files-with-matches" |
                    "follow" | "skip-snapshot-tests" | "include-off" | "include-metadata") {
                    result.bool_flags.insert(k);
                } else if k == "json" || k == "debug-query" || k == "error" || k == "warning" || k == "info" || k == "hint" || k == "off" {
                    // Optional value flags
                    let next_val = args.get(i+1).filter(|v| !v.starts_with('-'));
                    if let Some(v) = next_val {
                        result.flags.insert(k, Some(v.clone()));
                        i += 2;
                        continue;
                    } else {
                        result.flags.insert(k, None);
                    }
                } else {
                    // Expect a value
                    if let Some(val) = args.get(i+1) {
                        if !val.starts_with('-') || val == "-" {
                            if matches!(k.as_str(), "no-ignore" | "globs") {
                                result.multi_flags.entry(k).or_default().push(val.clone());
                            } else {
                                result.flags.insert(k, Some(val.clone()));
                            }
                            i += 2;
                            continue;
                        } else {
                            result.flags.insert(k, None);
                        }
                    } else {
                        result.flags.insert(k, None);
                    }
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    'h' => { result.bool_flags.insert("help".to_string()); }
                    'V' => { result.bool_flags.insert("version".to_string()); }
                    'i' => { result.bool_flags.insert("interactive".to_string()); }
                    'U' => { result.bool_flags.insert("update-all".to_string()); }
                    'p' | 'r' | 'l' | 'c' | 'j' | 'A' | 'B' | 'C' | 't' | 'f' => {
                        // These take values
                        let long = match ch {
                            'p' => "pattern",
                            'r' => "rewrite",
                            'l' => "lang",
                            'c' => "config",
                            'j' => "threads",
                            'A' => "after",
                            'B' => "before",
                            'C' => "context",
                            't' => "test-dir",
                            'f' => "filter",
                            _ => unreachable!(),
                        };
                        // Value is rest of this arg or next arg
                        let val = if j + 1 < chars.len() {
                            let v: String = chars[j+1..].iter().collect();
                            j = chars.len() - 1;
                            v
                        } else if let Some(next) = args.get(i+1) {
                            i += 1;
                            next.clone()
                        } else {
                            String::new()
                        };
                        result.flags.insert(long.to_string(), Some(val));
                    }
                    _ => {}
                }
                j += 1;
            }
        } else {
            result.positional.push(arg.clone());
        }

        i += 1;
    }

    Ok(result)
}

fn run_cmd(prog: &str, args: &[String]) -> i32 {
    let args: Vec<String> = args.to_vec();

    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_run_help(prog);
        return 0;
    }

    let parsed = match parse_args(&args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    // Get pattern
    let pattern = match parsed.get("pattern") {
        Some(p) => p.to_string(),
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  --pattern <PATTERN>");
            eprintln!("");
            eprintln!("Usage: executable run --pattern <PATTERN> [PATHS]...");
            eprintln!("");
            eprintln!("For more information, try '--help'.");
            return 2;
        }
    };

    let rewrite = parsed.get("rewrite").map(|s| s.to_string());
    let lang_str = parsed.get("lang");
    let use_stdin = parsed.has("stdin");
    let json_mode = parsed.has("json");
    let json_style = parsed.get("json").unwrap_or("pretty");
    let color_mode = parsed.get("color").unwrap_or("auto");
    let heading_mode = parsed.get("heading").unwrap_or("auto");
    let after_ctx: usize = parsed.get("after").and_then(|s| s.parse().ok()).unwrap_or(0);
    let before_ctx: usize = parsed.get("before").and_then(|s| s.parse().ok()).unwrap_or(0);
    let context: usize = parsed.get("context").and_then(|s| s.parse().ok()).unwrap_or(0);
    let after_ctx = if context > 0 { context } else { after_ctx };
    let before_ctx = if context > 0 { context } else { before_ctx };
    let files_with_matches = parsed.has("files-with-matches");

    // Validate lang
    let lang = if let Some(ls) = lang_str {
        match Language::from_str(ls) {
            Some(l) => Some(l),
            None => {
                eprintln!("error: invalid value '{}' for '--lang <LANG>': {} is not supported!", ls, ls);
                eprintln!("");
                eprintln!("For more information, try '--help'.");
                return 2;
            }
        }
    } else {
        None
    };

    let use_color = should_use_color(color_mode);

    let mut all_matches = Vec::new();
    let mut found_any = false;

    if use_stdin {
        let mut source = String::new();
        io::stdin().read_to_string(&mut source).unwrap_or(0);

        let lang = match &lang {
            Some(l) => l.clone(),
            None => {
                eprintln!("error: language must be specified with --lang when using --stdin");
                return 1;
            }
        };

        let matches = find_matches(&pattern, &source, &lang);
        if !matches.is_empty() {
            found_any = true;
        }

        if files_with_matches {
            if !matches.is_empty() {
                println!("STDIN");
            }
        } else if json_mode {
            for m in &matches {
                let json = format_match_json(&m, &source, "STDIN", lang.display_name(), &rewrite, json_style, None);
                all_matches.push(json);
            }
        } else {
            print_text_matches(&matches, &source, "STDIN", use_color, heading_mode, before_ctx, after_ctx, &rewrite);
        }
    } else {
        let paths = if parsed.positional.is_empty() {
            vec![".".to_string()]
        } else {
            parsed.positional.clone()
        };

        let mut files = Vec::new();
        for path in &paths {
            collect_files(path, &lang, &mut files);
        }

        files.sort();

        for file_path in &files {
            let source = match fs::read_to_string(file_path) {
                Ok(s) => s,
                Err(_) => continue,
            };

            let file_lang = if let Some(l) = &lang {
                l.clone()
            } else {
                let ext = Path::new(file_path).extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("");
                match Language::from_ext(ext) {
                    Some(l) => l,
                    None => continue,
                }
            };

            let matches = find_matches(&pattern, &source, &file_lang);
            if !matches.is_empty() {
                found_any = true;
            }

            if files_with_matches {
                if !matches.is_empty() {
                    println!("{}", file_path);
                }
            } else if json_mode {
                for m in &matches {
                    let json = format_match_json(&m, &source, file_path, file_lang.display_name(), &rewrite, json_style, None);
                    all_matches.push(json);
                }
            } else {
                print_text_matches(&matches, &source, file_path, use_color, heading_mode, before_ctx, after_ctx, &rewrite);
            }
        }
    }

    if json_mode && !files_with_matches {
        match json_style {
            "stream" => {
                for json in &all_matches {
                    println!("{}", json);
                }
            }
            "compact" => {
                print!("[");
                for (i, json) in all_matches.iter().enumerate() {
                    // Compact: remove whitespace
                    let compact = compact_json(json);
                    if i > 0 { print!(","); }
                    print!("{}", compact);
                }
                println!("]");
            }
            _ => {
                // pretty (default)
                println!("[");
                for (i, json) in all_matches.iter().enumerate() {
                    print!("{}", json);
                    if i + 1 < all_matches.len() {
                        print!(",");
                    }
                    println!();
                }
                println!("]");
            }
        }
    }

    if found_any { 0 } else { 1 }
}

fn format_match_json(
    m: &MatchResult, 
    source: &str, 
    filename: &str, 
    lang: &str,
    rewrite: &Option<String>,
    _style: &str,
    rule_info: Option<(&str, &str, Option<&str>, &str)>,
) -> String {
    use crate::output::match_to_json;

    let mut json = match_to_json(m, source, filename, lang, rule_info);

    // If we have a rewrite, add replacement field
    if let Some(rw) = rewrite {
        let replacement = apply_rewrite(rw, m);
        // Insert replacement before "language" field
        // Find position after charCount closing
        if let Some(pos) = json.find("  \"language\":") {
            let insert = format!("  \"replacement\": {},\n  \"replacementOffsets\": {{\n    \"start\": {},\n    \"end\": {}\n  }},\n", 
                json_str(&replacement), m.start_byte, m.end_byte);
            json.insert_str(pos, &insert);
        }
    }

    json
}

fn apply_rewrite(rewrite: &str, m: &MatchResult) -> String {
    let mut result = rewrite.to_string();

    // Replace $NAME with bound values (single vars first, longer names first to avoid partial replacements)
    let mut replacements: Vec<(String, String)> = m.single_vars.iter()
        .map(|(k, v)| (format!("${}", k), v.text.clone()))
        .collect();
    replacements.sort_by(|a, b| b.0.len().cmp(&a.0.len()));

    for (pat, val) in &replacements {
        result = result.replace(pat, val);
    }

    // Replace $$$NAME with multi-bound values
    let mut multi_replacements: Vec<(String, String)> = m.multi_vars.iter()
        .map(|(k, v)| {
            let text = v.items.iter().map(|i| i.text.as_str()).collect::<Vec<_>>().join("");
            (format!("$$${}", k), text)
        })
        .collect();
    multi_replacements.sort_by(|a, b| b.0.len().cmp(&a.0.len()));

    for (pat, val) in &multi_replacements {
        result = result.replace(pat, val);
    }

    result
}

fn should_use_color(mode: &str) -> bool {
    match mode {
        "never" => false,
        "always" | "ansi" => true,
        _ => {
            // auto - check if stdout is a tty
            // Since we can't easily check this in std, default to false when piped
            false
        }
    }
}

fn collect_files(path: &str, lang: &Option<Language>, files: &mut Vec<String>) {
    let p = Path::new(path);
    if p.is_file() {
        if should_include_file(p, lang) {
            files.push(path.to_string());
        }
        return;
    }

    if p.is_dir() {
        let entries = match fs::read_dir(p) {
            Ok(e) => e,
            Err(_) => return,
        };

        for entry in entries {
            let entry = match entry {
                Ok(e) => e,
                Err(_) => continue,
            };

            let entry_path = entry.path();
            let name = entry.file_name();
            let name_str = name.to_string_lossy();

            // Skip hidden files/dirs
            if name_str.starts_with('.') {
                continue;
            }

            if entry_path.is_dir() {
                collect_files(&entry_path.to_string_lossy(), lang, files);
            } else if entry_path.is_file() {
                if should_include_file(&entry_path, lang) {
                    files.push(entry_path.to_string_lossy().to_string());
                }
            }
        }
    }
}

fn should_include_file(p: &Path, lang: &Option<Language>) -> bool {
    let ext = p.extension().and_then(|e| e.to_str()).unwrap_or("");

    if let Some(l) = lang {
        Language::from_ext(ext).map_or(false, |file_lang| file_lang == *l)
    } else {
        Language::from_ext(ext).is_some()
    }
}

fn print_text_matches(
    matches: &[MatchResult],
    source: &str,
    filename: &str,
    use_color: bool,
    heading_mode: &str,
    before_ctx: usize,
    after_ctx: usize,
    rewrite: &Option<String>,
) {
    if matches.is_empty() {
        return;
    }

    let use_heading = match heading_mode {
        "always" => true,
        "never" => false,
        _ => false, // auto - false for non-tty
    };

    // Get source lines
    let lines: Vec<&str> = source.split('\n').collect();

    if use_heading {
        println!("{}", filename);
    }

    if rewrite.is_some() {
        // Print diff-like output
        print_diff_output(matches, source, filename, rewrite.as_deref().unwrap(), use_heading);
        return;
    }

    // Collect all line ranges to print (with context)
    let mut line_ranges: Vec<(usize, usize, bool)> = Vec::new(); // (start, end, is_match)

    for m in matches {
        let match_start_line = m.start_row;
        let match_end_line = m.end_row;

        let ctx_start = if match_start_line >= before_ctx { match_start_line - before_ctx } else { 0 };
        let ctx_end = (match_end_line + after_ctx).min(lines.len().saturating_sub(1));

        line_ranges.push((ctx_start, ctx_end, true));
    }

    // Merge overlapping ranges
    line_ranges.sort_by_key(|(s, _, _)| *s);
    let mut merged: Vec<(usize, usize)> = Vec::new();
    for (start, end, _) in line_ranges {
        if let Some(last) = merged.last_mut() {
            if start <= last.1 + 1 {
                last.1 = last.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }

    // Print the lines
    let mut printed_separator = false;
    for (range_idx, (range_start, range_end)) in merged.iter().enumerate() {
        if range_idx > 0 && !use_heading {
            // Print separator between non-adjacent ranges
        }

        for line_idx in *range_start..=*range_end {
            if line_idx >= lines.len() {
                break;
            }
            let line = lines[line_idx];
            let line_num = line_idx + 1;

            if use_heading {
                print!("{}│{}", line_num, line);
                println!();
            } else {
                println!("{}:{}:{}", filename, line_num, line);
            }
        }
    }

    if use_heading {
        println!();
    }
}

fn print_diff_output(
    matches: &[MatchResult],
    source: &str,
    filename: &str,
    rewrite: &str,
    use_heading: bool,
) {
    // Print diff-like output
    let lines: Vec<&str> = source.split('\n').collect();

    println!("{}", filename);

    for m in matches {
        let replacement = apply_rewrite(rewrite, m);
        let match_start_line = m.start_row;
        let match_end_line = m.end_row;

        // Print the diff header
        println!("@@ -{},{} +{},{} @@", match_start_line, 1, match_start_line, 1);

        // Print removed lines
        for line_idx in match_start_line..=match_end_line {
            if line_idx < lines.len() {
                let line_num = line_idx + 1;
                println!("{}  │-{}", line_num, lines[line_idx]);
            }
        }

        // Print added lines (replacement)
        for (i, rline) in replacement.lines().enumerate() {
            println!("  {}│+{}", match_start_line + 1 + i, rline);
        }
    }
}

fn scan_cmd(prog: &str, args: &[String]) -> i32 {
    let args: Vec<String> = args.to_vec();

    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_scan_help(prog);
        return 0;
    }

    let parsed = match parse_args(&args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };

    let rule_file = parsed.get("rule").map(|s| s.to_string());
    let inline_rules = parsed.get("inline-rules").map(|s| s.to_string());
    let json_mode = parsed.has("json");
    let json_style = parsed.get("json").unwrap_or("pretty");
    let color_mode = parsed.get("color").unwrap_or("auto");
    let report_style = parsed.get("report-style").unwrap_or("rich");
    let use_color = should_use_color(color_mode);

    let paths = if parsed.positional.is_empty() {
        vec![".".to_string()]
    } else {
        parsed.positional.clone()
    };

    // Load rules
    let rules = if let Some(rf) = &rule_file {
        match load_rule_file(rf) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: failed to load rule file '{}': {}", rf, e);
                return 1;
            }
        }
    } else if let Some(ir) = &inline_rules {
        match parse_rules_yaml(ir) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: failed to parse inline rules: {}", e);
                return 1;
            }
        }
    } else {
        // Try to find sgconfig.yml
        let config_file = parsed.get("config").unwrap_or("sgconfig.yml");
        match load_config_rules(config_file) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: {}", e);
                return 1;
            }
        }
    };

    let mut all_matches = Vec::new();
    let mut found_any = false;

    let use_stdin = parsed.has("stdin");

    if use_stdin {
        let mut source = String::new();
        io::stdin().read_to_string(&mut source).unwrap_or(0);

        for rule in &rules {
            let lang = match Language::from_str(&rule.language) {
                Some(l) => l,
                None => continue,
            };

            let matches = find_matches(&rule.pattern, &source, &lang);
            if !matches.is_empty() {
                found_any = true;
            }

            if json_mode {
                for m in &matches {
                    let json = format_match_json_scan(m, &source, "STDIN", lang.display_name(), rule);
                    all_matches.push(json);
                }
            } else {
                for m in &matches {
                    print_scan_match(m, &source, "STDIN", rule, use_color, report_style);
                }
            }
        }
    } else {
        let mut files = Vec::new();
        for path in &paths {
            collect_files_all(path, &mut files);
        }
        files.sort();

        for file_path in &files {
            let source = match fs::read_to_string(file_path) {
                Ok(s) => s,
                Err(_) => continue,
            };

            let ext = Path::new(file_path).extension()
                .and_then(|e| e.to_str())
                .unwrap_or("");
            let file_lang = match Language::from_ext(ext) {
                Some(l) => l,
                None => continue,
            };

            for rule in &rules {
                let rule_lang = match Language::from_str(&rule.language) {
                    Some(l) => l,
                    None => continue,
                };

                if rule_lang != file_lang {
                    continue;
                }

                let matches = find_matches(&rule.pattern, &source, &file_lang);
                if !matches.is_empty() {
                    found_any = true;
                }

                if json_mode {
                    for m in &matches {
                        let json = format_match_json_scan(m, &source, file_path, file_lang.display_name(), rule);
                        all_matches.push(json);
                    }
                } else {
                    for m in &matches {
                        print_scan_match(m, &source, file_path, rule, use_color, report_style);
                    }
                }
            }
        }
    }

    if json_mode {
        match json_style {
            "stream" => {
                for json in &all_matches {
                    println!("{}", json);
                }
            }
            _ => {
                println!("[");
                for (i, json) in all_matches.iter().enumerate() {
                    print!("{}", json);
                    if i + 1 < all_matches.len() {
                        print!(",");
                    }
                    println!();
                }
                println!("]");
            }
        }
    }

    if found_any { 0 } else { 1 }
}

fn collect_files_all(path: &str, files: &mut Vec<String>) {
    collect_files(path, &None, files);
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub id: String,
    pub language: String,
    pub pattern: String,
    pub message: String,
    pub severity: String,
    pub note: Option<String>,
}

fn load_rule_file(path: &str) -> Result<Vec<Rule>, String> {
    let content = fs::read_to_string(path)
        .map_err(|e| format!("Cannot read file: {}", e))?;
    parse_rules_yaml(&content)
}

fn parse_rules_yaml(yaml: &str) -> Result<Vec<Rule>, String> {
    let mut rules = Vec::new();

    // Simple YAML parser for rule format
    for doc in yaml.split("---") {
        let doc = doc.trim();
        if doc.is_empty() {
            continue;
        }

        if let Some(rule) = parse_single_rule(doc) {
            rules.push(rule);
        }
    }

    if rules.is_empty() {
        return Err("No valid rules found in YAML".to_string());
    }

    Ok(rules)
}

fn parse_single_rule(yaml: &str) -> Option<Rule> {
    let id = extract_yaml_str(yaml, "id")?;
    let language = extract_yaml_str(yaml, "language")?;
    let pattern = extract_rule_pattern(yaml)?;
    let message = extract_yaml_str(yaml, "message").unwrap_or_else(|| id.clone());
    let severity = extract_yaml_str(yaml, "severity").unwrap_or_else(|| "warning".to_string());
    let note = extract_yaml_str(yaml, "note");

    Some(Rule { id, language, pattern, message, severity, note })
}

fn extract_yaml_str(yaml: &str, key: &str) -> Option<String> {
    for line in yaml.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with(&format!("{}:", key)) {
            let val = trimmed[key.len()+1..].trim();
            // Remove surrounding quotes if present
            let val = if (val.starts_with('"') && val.ends_with('"')) ||
                         (val.starts_with('\'') && val.ends_with('\'')) {
                val[1..val.len()-1].to_string()
            } else {
                val.to_string()
            };
            if !val.is_empty() {
                return Some(val);
            }
        }
    }
    None
}

fn extract_rule_pattern(yaml: &str) -> Option<String> {
    // Look for: rule:\n  pattern: <PATTERN>
    // Or: rule:\n  pattern: |\n    <multiline>
    let mut in_rule = false;
    let mut in_pattern = false;
    let mut multiline = false;
    let mut pattern_lines = Vec::new();
    let mut pattern_indent = 0;

    for line in yaml.lines() {
        let trimmed = line.trim();

        if trimmed == "rule:" || trimmed.starts_with("rule:") {
            in_rule = true;
            in_pattern = false;
            continue;
        }

        if in_rule {
            let indent = line.len() - line.trim_start().len();

            if trimmed.starts_with("pattern:") {
                let val = trimmed["pattern:".len()..].trim();
                if val == "|" || val == "|-" {
                    in_pattern = true;
                    multiline = true;
                    pattern_indent = 0;
                } else if !val.is_empty() {
                    let val = if (val.starts_with('"') && val.ends_with('"')) ||
                                 (val.starts_with('\'') && val.ends_with('\'')) {
                        val[1..val.len()-1].to_string()
                    } else {
                        val.to_string()
                    };
                    return Some(val);
                }
                continue;
            }

            if in_pattern && multiline {
                if line.trim().is_empty() {
                    pattern_lines.push(String::new());
                    continue;
                }
                let cur_indent = line.len() - line.trim_start().len();
                if pattern_indent == 0 && !line.trim().is_empty() {
                    pattern_indent = cur_indent;
                }
                if cur_indent < pattern_indent && !line.trim().is_empty() {
                    // End of multiline pattern
                    break;
                }
                let stripped = if cur_indent >= pattern_indent {
                    &line[pattern_indent..]
                } else {
                    line.trim()
                };
                pattern_lines.push(stripped.to_string());
                continue;
            }

            // If we see something at lower indent, we're out of rule section
            if indent <= 0 && !trimmed.is_empty() && !trimmed.starts_with(' ') && !trimmed.starts_with('\t') {
                in_rule = false;
            }
        }
    }

    if !pattern_lines.is_empty() {
        Some(pattern_lines.join("\n").trim().to_string())
    } else {
        None
    }
}

fn load_config_rules(config_file: &str) -> Result<Vec<Rule>, String> {
    let config = fs::read_to_string(config_file)
        .map_err(|e| format!("Cannot read config file '{}': {}. Provide a rule file with --rule.", config_file, e))?;

    // Parse sgconfig.yml to get rule dirs
    let rule_dirs = extract_yaml_list(&config, "ruleDirs");

    let mut all_rules = Vec::new();
    for dir in rule_dirs {
        if let Ok(entries) = fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.extension().and_then(|e| e.to_str()) == Some("yml") ||
                   path.extension().and_then(|e| e.to_str()) == Some("yaml") {
                    if let Ok(rules) = load_rule_file(&path.to_string_lossy()) {
                        all_rules.extend(rules);
                    }
                }
            }
        }
    }

    Ok(all_rules)
}

fn extract_yaml_list(yaml: &str, key: &str) -> Vec<String> {
    let mut result = Vec::new();
    let mut in_list = false;

    for line in yaml.lines() {
        let trimmed = line.trim();
        if trimmed == &format!("{}:", key) {
            in_list = true;
            continue;
        }
        if in_list {
            if trimmed.starts_with("- ") {
                result.push(trimmed[2..].trim().to_string());
            } else if !trimmed.is_empty() && !trimmed.starts_with(' ') && !trimmed.starts_with('\t') {
                break;
            }
        }
    }

    result
}

fn format_match_json_scan(
    m: &MatchResult,
