fn find_rule_dir_from_config(config_file: &str) -> Option<String> {
    let config = fs::read_to_string(config_file).ok()?;
    let dirs = extract_yaml_list(&config, "ruleDirs");

    // Return the relative path if possible
    let cwd = std::env::current_dir().ok()?;
    for dir in dirs {
        let p = std::path::PathBuf::from(&dir);
        if let Ok(rel) = p.strip_prefix(&cwd) {
            return Some(rel.to_string_lossy().to_string());
        }
        // If absolute path matches current dir prefix
        return Some(dir);
    }
    None
}

