fn print_bash_completions(prog: &str) {
    let name = prog.replace('-', "_").replace('/', "_");
    println!("_{name}() {{", name=name);
    println!("    local i cur prev opts cmd");
    println!("    COMPREPLY=()");
    println!("    if [[ \"${{BASH_VERSINFO[0]}}\" -ge 4 ]]; then");
    println!("        cur=\"$2\"");
    println!("    else");
    println!("        cur=\"${{COMP_WORDS[COMP_CWORD]}}\"");
    println!("    fi");
    println!("    prev=\"$3\"");
    println!("    cmd=\"\"");
    println!("    opts=\"\"");
    println!("");
    println!("    for i in \"${{COMP_WORDS[@]:0:COMP_CWORD}}\"");
    println!("    do");
    println!("        case \"${{cmd}},${{i}}\" in");
    println!("            \",$1\")");
    println!("                cmd=\"{name}\"", name=name);
    println!("                ;;");
    println!("            {name},completions)", name=name);
    println!("                cmd=\"{name}__subcmd__completions\"", name=name);
    println!("                ;;");
    println!("            {name},help)", name=name);
    println!("                cmd=\"{name}__subcmd__help\"", name=name);
    println!("                ;;");
    println!("            {name},lsp)", name=name);
    println!("                cmd=\"{name}__subcmd__lsp\"", name=name);
    println!("                ;;");
    println!("            {name},new)", name=name);
    println!("                cmd=\"{name}__subcmd__new\"", name=name);
    println!("                ;;");
    // More completions...
    println!("        esac");
    println!("    done");
    println!("}}");
    println!("complete -F _{name} -o nosort -o bashdefault -o default {prog}", name=name, prog=prog);
}

