fn print_scan_match(
    m: &MatchResult,
    source: &str,
    filename: &str,
    rule: &Rule,
    use_color: bool,
    report_style: &str,
) {
    let lines: Vec<&str> = source.split('\n').collect();
    let line_num = m.start_row + 1;
    let col_num = m.start_col + 1;

    match report_style {
        "short" => {
            println!("{}[{}]: {}", rule.severity, rule.id, rule.message);
            println!("  {}:{}:{}", filename, line_num, col_num);
        }
        "medium" => {
            println!("{}[{}]: {}", rule.severity, rule.id, rule.message);
            println!("  --> {}:{}:{}", filename, line_num, col_num);
            if let Some(n) = &rule.note {
                println!("  note: {}", n);
            }
        }
        _ => {
            // rich (default)
            println!("{}[{}]: {}", rule.severity, rule.id, rule.message);
            println!("  ┌─ {}:{}:{}", filename, line_num, col_num);
            println!("  │");

            for line_idx in m.start_row..=m.end_row {
                if line_idx >= lines.len() {
                    break;
                }
                let lnum = line_idx + 1;
                let line = lines[line_idx];
                println!("{} │ {}", lnum, line);

                // Print underline
                let start_col = if line_idx == m.start_row { m.start_col } else { 0 };
                let end_col = if line_idx == m.end_row { m.end_col } else { line.len() };

                let spaces: String = " ".repeat(lnum.to_string().len() + 1 + 1 + start_col);
                let underline: String = "^".repeat((end_col - start_col).max(1));
                println!("{} │{}{}", " ".repeat(lnum.to_string().len()), spaces, underline);
            }

            println!();
        }
    }
}

