fn new_rule_cmd(prog: &str, args: &[String]) -> i32 {
    let parsed = match parse_args(args) {
        Ok(a) => a,
        Err(e) => { eprintln!("error: {}", e); return 1; }
    };

    let yes = parsed.has("yes") || parsed.has("y");
    let name = parsed.positional.get(0).cloned();
    let lang = parsed.get("lang").map(|s| s.to_string());

    if !yes {
        eprintln!("error: interactive mode not supported, use --yes flag");
        return 1;
    }

    let name = match name {
        Some(n) => n,
        None => {
            eprintln!("error: rule name is required");
            return 1;
        }
    };

    let lang = match lang {
        Some(l) => l,
        None => {
            eprintln!("error: language is required (use --lang)");
            return 1;
        }
    };

    let lang_obj = match Language::from_str(&lang) {
        Some(l) => l,
        None => {
            eprintln!("error: unsupported language: {}", lang);
            return 1;
        }
    };

    // Find rule dir from sgconfig.yml
    let rule_dir = find_rule_dir_from_config("sgconfig.yml").unwrap_or_else(|| "rules".to_string());
    let test_dir = find_test_dir_from_config("sgconfig.yml").unwrap_or_else(|| "rule-tests".to_string());

    // Create rule file
    let rule_path = format!("{}/{}.yml", rule_dir, name);
    let rule_content = format!(
        "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\nid: {}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\nlanguage: {}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
        name, lang_obj.display_name()
    );

    if let Err(e) = fs::write(&rule_path, &rule_content) {
        eprintln!("error: failed to write rule file: {}", e);
        return 1;
    }
    eprintln!("Created rules at {}", rule_path);

    // Create test file
    let test_path = format!("{}/{}-test.yml", test_dir, name);
    let test_content = format!("id: {}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n", name);

    if let Err(e) = fs::write(&test_path, &test_content) {
        eprintln!("error: failed to write test file: {}", e);
        return 1;
    }
    eprintln!("Created test at {}", test_path);

    0
}

