//! Core pattern matching logic
use crate::lang::Language;
use crate::pattern::{PatToken, MetaBinding, MultiBinding, MatchResult, parse_meta_pattern};
use crate::parse::{TokenKind, Tokenizer};
use std::collections::HashMap;

/// A source token with position info
#[derive(Debug, Clone)]
struct SrcToken {
    text: String,
    kind: TokenKind,
    start_byte: usize,
    end_byte: usize,
    start_row: usize,
    start_col: usize,
    end_row: usize,
    end_col: usize,
    depth: i32, // nesting depth
}

/// Tokenize source code into a flat list of tokens with depth info
fn tokenize_with_depth(source: &str, lang: &Language) -> Vec<SrcToken> {
    let bytes = source.as_bytes();
    let mut tokenizer = Tokenizer::new(bytes, lang);
    let raw_tokens = tokenizer.tokenize_significant();

    let mut depth = 0i32;
    let mut result = Vec::new();

    for tok in raw_tokens {
        if matches!(tok.kind, TokenKind::Eof) {
            break;
        }
        if matches!(tok.kind, TokenKind::Newline) {
            continue;
        }

        let d = match &tok.kind {
            TokenKind::OpenParen | TokenKind::OpenBrace | TokenKind::OpenBracket => {
                let old = depth;
                depth += 1;
                old
            }
            TokenKind::CloseParen | TokenKind::CloseBrace | TokenKind::CloseBracket => {
                depth -= 1;
                if depth < 0 { depth = 0; }
                depth
            }
            _ => depth,
        };

        result.push(SrcToken {
            text: tok.text,
            kind: tok.kind,
            start_byte: tok.start_byte,
            end_byte: tok.end_byte,
            start_row: tok.start_row,
            start_col: tok.start_col,
            end_row: tok.end_row,
            end_col: tok.end_col,
            depth: d,
        });
    }

    result
}

/// Get the extent of a "node" starting at position `start`
/// A node is either a single token, a bracketed group, or an identifier+call chain
fn node_extent(tokens: &[SrcToken], start: usize) -> usize {
    if start >= tokens.len() {
        return start;
    }

    let tok = &tokens[start];

    match &tok.kind {
        TokenKind::OpenParen | TokenKind::OpenBrace | TokenKind::OpenBracket => {
            // Find matching close bracket
            let open_depth = tok.depth;
            let mut i = start + 1;
            while i < tokens.len() {
                let t = &tokens[i];
                if matches!(t.kind, TokenKind::CloseParen | TokenKind::CloseBrace | TokenKind::CloseBracket)
                    && t.depth <= open_depth {
                    return i + 1;
                }
                i += 1;
            }
            tokens.len()
        }
        _ => {
            // For identifiers/literals, check if followed by ( or [ or {
            // This handles call expressions like foo(...), array access foo[...], etc.
            let mut end = start + 1;
            while end < tokens.len() {
                match &tokens[end].kind {
                    TokenKind::OpenParen | TokenKind::OpenBracket | TokenKind::OpenBrace => {
                        // This is a call/subscript/generic expression - include the group
                        let close_end = {
                            let open_depth = tokens[end].depth;
                            let mut i = end + 1;
                            while i < tokens.len() {
                                let t = &tokens[i];
                                if matches!(t.kind, TokenKind::CloseParen | TokenKind::CloseBrace | TokenKind::CloseBracket)
                                    && t.depth <= open_depth {
                                    break;
                                }
                                i += 1;
                            }
                            i + 1
                        };
                        end = close_end.min(tokens.len());
                    }
                    TokenKind::Op(s) if s == "." || s == "::" || s == "->" => {
                        // Member access - include the next identifier
                        end += 1; // consume the operator
                        if end < tokens.len() && matches!(tokens[end].kind, TokenKind::Ident | TokenKind::Op(_)) {
                            end += 1; // include the field name
                        }
                    }
                    _ => break,
                }
            }
            end
        }
    }
}

/// Get text from source bytes
fn source_slice(source: &str, start: usize, end: usize) -> &str {
    source.get(start..end).unwrap_or("")
}

/// Match pattern tokens against source tokens starting at position `src_pos`
/// Returns end_pos if match succeeds
fn try_match(
    pattern: &[PatToken],
    src: &[SrcToken],
    source: &str,
    pat_pos: usize,
    src_pos: usize,
    bindings: &mut HashMap<String, MetaBinding>,
    multi_bindings: &mut HashMap<String, MultiBinding>,
) -> Option<usize> {
    if pat_pos == pattern.len() {
        return Some(src_pos);
    }

    if src_pos > src.len() {
        return None;
    }

    let pat = &pattern[pat_pos];

    match pat {
        PatToken::MetaVarMulti(name) => {
            // Check if already bound
            if let Some(existing) = multi_bindings.get(name) {
                let expected = existing.items.clone();
                let end = src_pos + expected.len();
                if end > src.len() {
                    return None;
                }
                for (i, item) in expected.iter().enumerate() {
                    if src[src_pos + i].text != item.text {
                        return None;
                    }
                }
                return try_match(pattern, src, source, pat_pos + 1, end, bindings, multi_bindings);
            }

            // Try matching different numbers of tokens
            let base_depth = src.get(src_pos).map_or(0, |t| t.depth);

            // Try from 0 tokens up to all remaining tokens at same depth level
            let mut end = src_pos;

            loop {
                let mut new_bindings = bindings.clone();
                let mut new_multi_bindings = multi_bindings.clone();

                let items: Vec<MetaBinding> = src[src_pos..end].iter().map(|t| MetaBinding {
                    text: source_slice(source, t.start_byte, t.end_byte).to_string(),
