# In tokenize_with_depth for 'foo()':
# foo: depth=0, kind=Ident
# (: depth=0, kind=OpenParen
# ): depth=0, kind=CloseParen
#
# node_extent for 'foo' at pos 0:
#   end = 1 (just 'foo')
#   check tokens[1] = '(' OpenParen -> trigger extension
#   find close bracket for '(' at depth 0
#     depth_start = 0 (depth of '(')
#     But wait, ')' has depth=0 (after decrement), not depth <= 0?
#     Actually looking at my code: 
#     "if matches!(t.kind, TokenKind::CloseParen...) && t.depth <= open_depth"
#     open_depth = tokens[end].depth = 0 (depth of '(')
#     ')' has depth 0 <= 0 -> YES, matched!
#     close_end = i + 1 = 2 + 1 = 3
#   end = 3
# So node_extent('foo') = 3

