# Now add the print_debug_query function to cli.rs
cat >> /workspace/ast-grep-impl/src/cli.rs << 'RUST_EOF'

fn print_debug_query(pattern: &str, lang: &Language, format: &str) {
    use crate::pattern::{PatToken, parse_meta_pattern};
    use crate::parse::TokenKind;

    match format {
        "pattern" => {
            let tokens = parse_meta_pattern(pattern, lang);
            println!("Debug Pattern:");
            // Indent based on nesting
            let mut depth = 0i32;
            for tok in &tokens {
                match tok {
                    PatToken::Literal { text, kind } => {
                        match kind {
                            TokenKind::OpenBrace => {
                                println!("{}{}",  "  ".repeat(depth as usize), text);
                                depth += 1;
                            }
                            TokenKind::CloseBrace => {
                                depth -= 1;
                                println!("{}{}", "  ".repeat(depth.max(0) as usize), text);
                            }
                            _ => {
                                println!("{}{}", "  ".repeat(depth as usize), text);
                            }
                        }
