# The MetaVarMulti captures individual tokens. Let me modify it to capture "nodes" instead.
# A "node" for $$$ARGS would be expressions separated by commas.
# A "node" for $$$BODY would be statements.

# The key change: instead of collecting individual tokens one by one,
# collect "node extents" (using node_extent) one by one.

cat > /tmp/fix_multi.py << 'EOF'
content = open('/workspace/ast-grep-impl/src/matcher.rs').read()

# Find the loop that advances end one token at a time
old_loop = '''            // Try from 0 tokens up to all remaining tokens at same depth level
            let mut end = src_pos;

            loop {
                let mut new_bindings = bindings.clone();
                let mut new_multi_bindings = multi_bindings.clone();

                let items: Vec<MetaBinding> = src[src_pos..end].iter().map(|t| MetaBinding {
                    text: source_slice(source, t.start_byte, t.end_byte).to_string(),
                    start_byte: t.start_byte,
                    end_byte: t.end_byte,
                    start_row: t.start_row,
                    start_col: t.start_col,
                    end_row: t.end_row,
                    end_col: t.end_col,
                }).collect();

                new_multi_bindings.insert(name.clone(), MultiBinding { items });

                if let Some(result) = try_match(pattern, src, source, pat_pos + 1, end, &mut new_bindings, &mut new_multi_bindings) {
                    *bindings = new_bindings;
                    *multi_bindings = new_multi_bindings;
                    return Some(result);
                }

                if end >= src.len() {
                    break;
                }

                // Advance by one "node"
                let next = node_extent(src, end);
                if next <= end {
                    end += 1;
                } else {
                    end = next;
                }
            }

            None'''

new_loop = '''            // Try from 0 nodes up to all remaining nodes
            let mut end = src_pos;

            // Build list of possible end positions by stepping through nodes
            let mut positions = vec![src_pos];
            let mut cur = src_pos;
            while cur < src.len() {
                let next = node_extent(src, cur);
                if next > cur {
                    positions.push(next);
                    cur = next;
                } else {
                    cur += 1;
                    positions.push(cur);
                }
            }
            positions.dedup();

            for &end in &positions {
                let mut new_bindings = bindings.clone();
                let mut new_multi_bindings = multi_bindings.clone();

                // Build items as node-level bindings
                let mut items: Vec<MetaBinding> = Vec::new();
                let mut cur2 = src_pos;
                while cur2 < end {
                    let next2 = node_extent(src, cur2);
                    let node_end = if next2 > cur2 { next2 } else { cur2 + 1 };
                    let node_end = node_end.min(end);
                    if node_end > cur2 && cur2 < src.len() {
                        let start_byte = src[cur2].start_byte;
                        let end_byte = src[node_end - 1].end_byte;
                        items.push(MetaBinding {
                            text: source_slice(source, start_byte, end_byte).to_string(),
                            start_byte,
                            end_byte,
                            start_row: src[cur2].start_row,
                            start_col: src[cur2].start_col,
                            end_row: src[node_end - 1].end_row,
                            end_col: src[node_end - 1].end_col,
                        });
                    }
                    cur2 = node_end;
                }

                new_multi_bindings.insert(name.clone(), MultiBinding { items });

                if let Some(result) = try_match(pattern, src, source, pat_pos + 1, end, &mut new_bindings, &mut new_multi_bindings) {
                    *bindings = new_bindings;
                    *multi_bindings = new_multi_bindings;
                    return Some(result);
                }
            }

            None'''

content = content.replace(old_loop, new_loop)
open('/workspace/ast-grep-impl/src/matcher.rs', 'w').write(content)
print("Done")
EOF
