                    total += 1;
                    let matches = find_matches(&rule.pattern, code, &rule_lang);
                    if !matches.is_empty() {
                        passed += 1;
                    } else {
                        failed += 1;
                        eprintln!("FAIL [{}] invalid case: {:?}", test_id, code);
                        eprintln!("  Expected match but found none");
                    }
                }
            }
        }
    }

    if total == 0 {
        eprintln!("No test cases found");
        return 0;
    }

    println!("{} tests passed, {} failed", passed, failed);

    if failed > 0 { 1 } else { 0 }
}

fn extract_yaml_string_list(yaml: &str, key: &str) -> Vec<String> {
    let mut result = Vec::new();
